<script setup lang="ts">
const route = useRoute()
const id = String(route.params.moduleId)
const { $api } = useNuxtApp()
const { data: pkg, error } = await useAsyncData(`package-${id}`, () => $api.package(id))
if (error.value || !pkg.value) throw createError({ statusCode: 404, statusMessage: 'Package not found' })
const latest = computed(() => pkg.value!.versions[0]!)
usePageSeo(`${pkg.value.name} · Open City Planner Packages`, pkg.value.description || `Registry details for ${pkg.value.name}.`, `/packages/${id}`)
</script>
<template>
  <div v-if="pkg" class="container-shell py-8"><nav class="text-sm text-slate-500" aria-label="Breadcrumb"><NuxtLink to="/packages">Packages</NuxtLink> <span aria-hidden="true">›</span> {{ pkg.name }}</nav><header class="mt-7 grid gap-6 lg:grid-cols-[1fr_320px]"><div class="flex gap-4"><PackageIcon :name="pkg.name" /><div><div class="flex flex-wrap items-center gap-3"><h1 class="page-title">{{ pkg.name }}</h1><PackageBadge :value="latest.channel" /></div><div class="mt-2"><PublisherBadge :publisher="pkg.publisher" :classification="pkg.classification" /></div><p class="mt-5 max-w-3xl text-slate-600">{{ pkg.description }}</p></div></div><DownloadCard :module-id="pkg.id" :release="latest" /></header><nav class="mt-9 flex gap-6 overflow-x-auto border-b border-slate-200 text-sm font-semibold" aria-label="Package sections"><a v-for="section in ['Overview','Versions','Compatibility','Provenance','Documentation','Source']" :key="section" :href="`#${section.toLowerCase()}`" class="border-b-2 border-transparent px-1 py-4 hover:border-brand-500">{{ section }}</a></nav><div class="mt-8 grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]"><div class="grid gap-6"><section id="overview" class="surface-card p-6"><h2 class="text-xl font-bold">Overview</h2><p class="mt-4 leading-7 text-slate-700">{{ pkg.description }}</p><dl class="mt-6 grid gap-4 sm:grid-cols-2"><div><dt class="muted-label">Latest version</dt><dd><NuxtLink :to="`/packages/${pkg.id}/${latest.version}`" class="text-link-700">{{ latest.version }}</NuxtLink></dd></div><div><dt class="muted-label">License</dt><dd>{{ pkg.license }}</dd></div><div><dt class="muted-label">Publisher</dt><dd>{{ pkg.publisher.name }}</dd></div><div><dt class="muted-label">Classification</dt><dd>{{ pkg.classification }}</dd></div></dl></section><section id="versions" class="surface-card p-6"><h2 class="text-xl font-bold">Versions</h2><ul class="mt-4 divide-y divide-slate-100"><li v-for="release in pkg.versions" :key="release.version" class="flex items-center justify-between py-4"><div><NuxtLink :to="`/packages/${pkg.id}/${release.version}`" class="font-bold text-link-700">{{ release.version }}</NuxtLink><p class="text-sm text-slate-500">Bundle format {{ release.bundle_format_version }}</p></div><PackageBadge :value="release.channel" /></li></ul></section><ProvenancePanel id="provenance" :pkg="pkg" :release="latest" /></div><aside id="compatibility" class="grid h-fit gap-5"><section class="surface-card p-5"><h2 class="font-bold">Compatibility</h2><dl class="mt-4 grid gap-3 text-sm"><div class="flex justify-between gap-3"><dt>Host</dt><dd class="font-mono">{{ latest.requires.host }}</dd></div><div class="flex justify-between gap-3"><dt>SDK</dt><dd class="font-mono">{{ latest.requires.sdk }}</dd></div></dl></section><section class="surface-card p-5"><h2 class="font-bold">Details</h2><dl class="mt-4 grid gap-3 text-sm"><div><dt class="muted-label">ID</dt><dd>{{ pkg.id }}</dd></div><div><dt class="muted-label">Channel</dt><dd class="capitalize">{{ latest.channel }}</dd></div><div><dt class="muted-label">Latest version</dt><dd>{{ latest.version }}</dd></div></dl></section><section id="documentation" class="surface-card p-5"><h2 class="font-bold">Links</h2><div class="mt-3 grid gap-2"><a v-if="pkg.documentation_url" :href="pkg.documentation_url" class="text-link-700">Documentation ↗</a><a id="source" :href="pkg.source_repository" class="text-link-700">Source repository ↗</a></div></section></aside></div></div>
</template>
